from lib import *
S = SS('x58')
steps = [
    step("WebFlux 在 Reactor Netty 上默认用多少个线程处理请求。机器有 10 个逻辑核心,100 个请求(每个新连接)分布在 reactor-http-nio-1 … reactor-http-nio-10 这 10 个线程上,每个线程正好 10 个——连接被轮流分给 event loop 线程。线程数等于逻辑核心数,不是 Tomcat 默认的 200。", t=tl(S(1)), mark=lidx(S(1), '分布在 10 个线程上'), done=lidx(S(1), '分布在 10 个线程上'), b=bars([['处理请求的线程数', 10, '10(= 逻辑核心数)'], ['每个线程处理的请求数', 10, '10(轮流分配)']], 10, done=[0, 1]), kv=KV([['WebFlux + Reactor Netty', '默认 event loop 线程数 = 核心数'], ['线程名', 'reactor-http-nio-N'], ['分配方式', '连接轮流分给线程'], ['对比 Tomcat', '默认最多 200 个工作线程']], ['WebFlux + Reactor Netty'])),
    step("把 event loop 线程数设成 2(-Dreactor.netty.ioWorkerCount=2):40 个请求只分布在 reactor-http-nio-1 和 reactor-http-nio-2,各 20 个。后面的阻塞实验用这个设置,让 2 个线程被占满的后果一眼可见。", t=tl(S(2)), mark=lidx(S(2), '分布在 2 个线程上'), done=lidx(S(2), '分布在 2 个线程上'), b=bars([['线程数', 2, '2'], ['每个线程处理的请求数', 20, '20']], 20, done=[0, 1]), kv=KV([['-Dreactor.netty.ioWorkerCount', '设置 event loop 线程数'], ['设成 2', '40 个请求分在 2 个线程上,各 20 个']], ['-Dreactor.netty.ioWorkerCount'])),
    step("阻塞调用放在哪里(event loop 线程只有 2 个,4 个并发请求,每个处理 500 ms,期间用新连接持续探测 /fast)。在 Mono.fromCallable 里 Thread.sleep(500) 没切线程:4 个请求耗时 611、611、1120、1125 ms——每个 event loop 线程要顺序处理 2 个;期间第一个 /fast 等了 1022 ms,因为两个线程都被占着。控制器方法直接返回 String、里面 Thread.sleep(500):同样 585、585、1096、1099 ms,第一个 /fast 等了 993 ms,线程是 reactor-http-nio-1/2。放到 subscribeOn(boundedElastic):4 个请求都是 595 ms,线程是 boundedElastic-1 … -4,探测的 /fast 最慢只有 9 ms。Mono.delayElement(500 ms)(非阻塞等待):4 个都是 579 ms,/fast 最慢 8 ms。", t=tl(S(3)), mark=lidx(S(3), '最慢 1022 ms', '最慢 993 ms', '[611, 611, 1120, 1125]', '[585, 585, 1096, 1099]'), done=lidx(S(3), '[595, 595, 595, 595]', '最慢 9 ms', '[579, 579, 579, 579]', '最慢 8 ms'), b=bars([['event loop 上 Thread.sleep:最慢的请求 ms', 1125, '1125'], ['event loop 上 Thread.sleep:/fast 最慢 ms', 1022, '1022'], ['offload 到 boundedElastic:最慢的请求 ms', 595, '595'], ['offload:/fast 最慢 ms', 9, '9']], 1125, mark=[0, 1], done=[2, 3]), kv=KV([['event loop 线程上阻塞', '2 个线程各自排队,别的请求(包括 /fast)跟着等'], ['控制器里直接 Thread.sleep', '同样阻塞 event loop 线程'], ['subscribeOn(boundedElastic)', '阻塞挪走,event loop 不受影响'], ['Mono.delayElement', '非阻塞等待,不占线程']], ['event loop 线程上阻塞'])),
    step("在 event loop 线程上调用 block()。Mono.fromSupplier 里调用 Mono.just(\"x\").delayElement(10ms).block():500,异常是 IllegalStateException: block()/blockFirst()/blockLast() are blocking, which is not supported in thread reactor-http-nio-2——Reactor 在非阻塞线程上直接拒绝 block()。同样的代码放到 subscribeOn(boundedElastic) 上:200,正常返回 x。Reactor 会替你拦住这一种阻塞,Thread.sleep 之类的它拦不住。", t=tl(S(4)), mark=lidx(S(4), 'call-block → 500'), done=lidx(S(4), 'call-block-offload → 200'), b=bars([['event loop 上 block() 的状态码', 500, '500'], ['boundedElastic 上 block() 的状态码', 200, '200']], 500, mark=[0], done=[1]), kv=KV([['event loop 上 block()', 'IllegalStateException,被直接拒绝'], ['boundedElastic 上 block()', '允许'], ['Thread.sleep / JDBC', '不会被拦,只会悄悄卡住 event loop'], ['检测', '生产里可以用 BlockHound 之类的工具(未验证)']], ['event loop 上 block()'])),
    step("非阻塞等待的好处:只有 2 个 event loop 线程,N 个并发请求各等 500 ms(Mono.delayElement)。50 个并发:全部 200,全部完成用了 622 ms;100 个:552 ms;200 个:557 ms。并发数翻几倍,总耗时几乎不变,2 个线程服务了 200 个同时挂着的请求。等待不占线程,这才是 WebFlux 用少量线程撑住大量并发的来源。", t=tl(S(5)), mark=lidx(S(5), '200 个并发'), done=lidx(S(5), '50 个并发', '100 个并发'), b=bars([['50 个并发的总耗时 ms', 622, '622'], ['100 个并发的总耗时 ms', 552, '552'], ['200 个并发的总耗时 ms', 557, '557']], 622, done=[0, 1, 2]), kv=KV([['event loop 线程', '只有 2 个'], ['并发 200 个、各等 500 ms', '557 ms 全部完成'], ['原因', '等待由定时器驱动,不占线程'], ['前提', '处理逻辑里没有阻塞调用']], ['原因'])),
]
A = mkartx('x58', 58, 'Spring,WebFlux,Reactor Netty,event loop,阻塞,线程模型,真实验证,动画演示',
    '实测 WebFlux 的线程模型:Reactor Netty 默认 event loop 线程数等于逻辑核心数(10),连接轮流分配;把线程数设成 2 之后,在 event loop 上 Thread.sleep(无论 Mono.fromCallable 里还是控制器直接 sleep)会让别的请求(包括 /fast)等到 1022 ms,subscribeOn(boundedElastic) 则只有 9 ms;event loop 线程上 block() 会被 Reactor 直接拒绝(500);非阻塞等待让 2 个线程撑住 200 个并发请求。',
    'WebFlux 默认有几个线程?在控制器里 Thread.sleep 或查 JDBC 会怎样?block() 为什么会报错?subscribeOn(boundedElastic) 能解决什么?为什么 WebFlux 用很少的线程就能扛很多并发?这篇在 Spring Boot 4.0.8 的 WebFlux 上把 event loop 线程数调到 2,用真实请求逐个验证。',
    [('10', 'WebFlux 默认处理请求的 event loop 线程数(等于本机逻辑核心数)'), ('1022 ms', '2 个 event loop 线程都被 Thread.sleep 占住时,一个本来只要几毫秒的 /fast 的等待时间(offload 之后是 9 ms)'), ('557 ms', '只有 2 个线程时,200 个并发的非阻塞等待请求(各等 500 ms)全部完成的时间')],
    [('线程数', '<p>event loop 线程数等于核心数,连接轮流分配。</p>'),
     ('调小线程数', '<p>设成 2 让阻塞的后果可见。</p>'),
     ('阻塞的后果', '<p>event loop 上阻塞会拖慢所有请求;offload 到 boundedElastic 则不影响。</p>'),
     ('block()', '<p>Reactor 在非阻塞线程上直接拒绝 block()。</p>'),
     ('非阻塞等待', '<p>等待不占线程,少量线程撑住大量并发。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的 SpringApplication(spring-boot-starter-webflux,Reactor Netty 1.3.7,Netty 4.2.17);每个请求新建连接(Connection: close);event loop 线程数通过 -Dreactor.netty.ioWorkerCount 设置;机器 10 个逻辑核心。之前试跑过一次 200 个并发请求的实验,第一次冲击刚启动的进程时有个别请求失败,正式记录的这次全部成功,结果在刚启动的进程上并不稳定',
     '没有验证:BlockHound 对阻塞调用的检测;WebFlux 在 Tomcat / Undertow 等 Servlet 容器上的线程模型;spring.threads.virtual.enabled 对 WebFlux 的影响(见第 60 篇);WebClient 在 event loop 上的连接池行为(见第 59 篇);响应式 JDBC(R2DBC)的线程(见第 61 篇);ioWorkerCount 取值对吞吐的影响'],
    '线程模型')
